def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    # Alive opponents
    alive = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive.append(o)

    # If no one alive, take what you can
    if not alive:
        return max(0.0, min(my_status['budget'], DAILY_SALARY * 0.4))

    # Extract yesterday bids from previous_trace
    prev_bids = []
    for o in alive:
        pt = o.get('previous_trace', {}) or {}
        b = pt.get('bid', None)
        if b is not None:
            try:
                prev_bids.append(float(b))
            except Exception:
                pass

    highest_prev = max(prev_bids) if prev_bids else 0.0

    # Base aggressiveness by current HP
    hp = float(my_status['hp'])
    budget = float(my_status['budget'])
    no_water_days = int(my_status['no_water_days'])

    # If we are at risk, bid high enough to secure water.
    if hp <= 2 or no_water_days >= 2:
        target = DAILY_SALARY * 0.85
    else:
        # If others were extremely aggressive yesterday, we can undercut to save budget.
        # Cindy/Eric showed very high bids (~115-128) while low-bid players died.
        if highest_prev >= DAILY_SALARY * 1.2:
            # Underbid relative to their peak while still trying to win at moderate supply.
            target = DAILY_SALARY * 0.55
        else:
            # Otherwise, bid around a mid level.
            target = DAILY_SALARY * 0.65

    # Adjust by supply: higher supply -> lower bid needed; lower supply -> slightly higher
    # Normalize supply within [MIN_SUPPLY, MAX_SUPPLY]
    if MAX_SUPPLY > MIN_SUPPLY:
        t = (supply - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY)
    else:
        t = 0.5
    # t in [0,1] ideally
    if t < 0.0:
        t = 0.0
    if t > 1.0:
        t = 1.0

    # When supply is low, increase bid; when high, decrease
    target = target * (1.10 - 0.20 * t)

    # Never bid more than budget
    bid = max(0.0, min(budget, target))

    # Small day-based modulation to avoid exact ties
    bid = bid * (0.98 + (day % 5) * 0.01)

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    MY_WATER_REQUIREMENT = 13
    MY_DAILY_SALARY = 150
    EPISODE_DAYS = 10

    current_day = day_context['day']
    current_supply = day_context['supply']

    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    num_alive_opponents = len(alive_opponents)

    if not alive_opponents:
        return min(my_status['budget'], MY_DAILY_SALARY * 0.1)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    base_bid_factor = 0.55

    if my_status['hp'] <= 2 or my_status['no_water_days'] >= 1:
        base_bid_factor = 0.95
    elif my_status['hp'] >= 8:
        base_bid_factor = 0.45

    effective_participants = num_alive_opponents + 1
    if effective_participants > 0:
        supply_per_participant = current_supply / effective_participants

        if supply_per_participant < MY_WATER_REQUIREMENT * 0.8:
            base_bid_factor += 0.20
        elif supply_per_participant < MY_WATER_REQUIREMENT * 1.2:
            base_bid_factor += 0.05
        elif supply_per_participant > MY_WATER_REQUIREMENT * 1.5:
            base_bid_factor -= 0.10

    if yesterday_bids:
        max_yesterday_bid = max(yesterday_bids)
        avg_yesterday_bid = sum(yesterday_bids) / len(yesterday_bids)

        if max_yesterday_bid >= MY_DAILY_SALARY * 0.8:
            base_bid_factor = max(base_bid_factor, (max_yesterday_bid + 5) / MY_DAILY_SALARY)
        elif max_yesterday_bid >= MY_DAILY_SALARY * 0.6:
            base_bid_factor = max(base_bid_factor, (avg_yesterday_bid + 2) / MY_DAILY_SALARY)
        else:
            if my_status['hp'] > 3:
                base_bid_factor = min(base_bid_factor, (avg_yesterday_bid + 1) / MY_DAILY_SALARY)

    remaining_days = EPISODE_DAYS - current_day
    if remaining_days <= 3:
        if my_status['hp'] <= 3:
             base_bid_factor = max(base_bid_factor, 0.98)
        else:
            base_bid_factor = max(base_bid_factor, 0.75)

    final_bid = MY_DAILY_SALARY * base_bid_factor

    final_bid = min(my_status['budget'], final_bid)

    if final_bid <= 0 and my_status['budget'] > 0:
        return 1.0
    elif my_status['budget'] <= 0:
        return 0.0

    if final_bid < 1.0 and my_status['budget'] >= 1.0:
        return 1.0

    return final_bid

